/bin/bash -lc "apply_patch <<'PATCH'
*** Begin Patch
*** Update File: Task.v
@@
   - apply not_in_append in Hfresh as [Hleft Hright].
-    split; intros (Hv1 & Hv2 & U1 & body1 & U2 & body2 & -> & -> & Hbody);
-      repeat split; auto; exists U1, body1, U2, body2; repeat split; auto;
-      intros arg1 arg2 Harg;
-      apply (lifting_equiv _ _ (fun w1 w2 => IHT2 X eta rho c w1 w2 Hright)).
-    + apply Hbody. apply (IHT1 X eta rho c _ _ Hleft). exact Harg.
-    + apply Hbody. apply (IHT1 X eta rho c _ _ Hleft). exact Harg.
-  - split; intros (Hv1 & Hv2 & body1 & body2 & -> & -> & Hbody);
-      repeat split; auto; exists body1, body2; repeat split; auto;
-      intros U1 U2 b HU1 HU2;
-      apply (lifting_equiv _ _ (fun w1 w2 => IHT X (b :: eta) rho c w1 w2 Hfresh));
-      apply Hbody; auto.
+    split; intros (Hv1 & Hv2 & U1 & body1 & U2 & body2 & Eq1 & Eq2 & Hbody);
+      split; [assumption|split; [assumption|]];
+      exists U1, body1, U2, body2; split; [assumption|split; [assumption|]];
+      intros arg1 arg2 Harg.
+    + apply (lifting_equiv _ _ (fun w1 w2 => IHT2 X eta rho c w1 w2 Hright)).
+      apply Hbody. apply (IHT1 X eta rho c _ _ Hleft). exact Harg.
+    + apply (lifting_equiv _ _ (fun w1 w2 => IHT2 X eta rho c w1 w2 Hright)).
+      apply Hbody. apply (IHT1 X eta rho c _ _ Hleft). exact Harg.
+  - split; intros (Hv1 & Hv2 & body1 & body2 & Eq1 & Eq2 & Hbody);
+      split; [assumption|split; [assumption|]];
+      exists body1, body2; split; [assumption|split; [assumption|]];
+      intros U1 U2 b HU1 HU2.
+    + apply (lifting_equiv _ _ (fun w1 w2 => IHT X (b :: eta) rho c w1 w2 Hfresh)).
+      apply Hbody; auto.
+    + apply (lifting_equiv _ _ (fun w1 w2 => IHT X (b :: eta) rho c w1 w2 Hfresh)).
+      apply Hbody; auto.
*** End Patch
PATCH
coqc -q Task.v"

